import {REPO,DATA_PATH,round,today,totals,shiftDate,dayFor,nextSession,validate,brief} from './model.js';
const icons={dashboard:'M3 3h7v7H3z M14 3h7v7h-7z M3 14h7v7H3z M14 14h7v7h-7z',food:'M5 3v7a3 3 0 0 0 6 0V3 M8 3v18 M19 3v18 M19 3c-5 2-5 9 0 9',training:'M3 8v8 M6 5v14 M6 12h12 M18 5v14 M21 8v8',history:'M3 11a9 9 0 1 1 2 7 M3 4v7h7 M12 7v6l4 2',settings:'M12 8a4 4 0 1 0 0 8 4 4 0 0 0 0-8 M12 2v3 M12 19v3 M2 12h3 M19 12h3 M5 5l2 2 M17 17l2 2 M5 19l2-2 M17 7l2-2',arrow:'M5 12h14 M14 7l5 5-5 5',left:'M14 6l-6 6 6 6',right:'M10 6l6 6-6 6',plus:'M12 5v14 M5 12h14',refresh:'M20 7a9 9 0 1 0 1 8 M20 2v5h-5',check:'M5 12l4 4L19 6',close:'M6 6l12 12 M6 18L18 6',flame:'M13 3c1 5 6 6 6 12a7 7 0 0 1-14 0c0-4 3-6 4-9 0 4 3 5 4-3Z',steps:'M8 3a2 2 0 1 0 0 4 2 2 0 0 0 0-4 M8 10l-2 5H3 M8 10l5 4 3-2 M8 10l4-3 4 2 M11 14l-1 7 M13 14l4 6',water:'M12 2S5 10 5 15a7 7 0 0 0 14 0c0-5-7-13-7-13Z',weight:'M4 5h16v16H4z M8 9h8 M12 9l2-3',coffee:'M4 8h12v9a4 4 0 0 1-4 4H8a4 4 0 0 1-4-4Z M16 9h2a3 3 0 0 1 0 6h-2 M7 2v3 M12 2v3',edit:'M4 20l4-1L20 7l-4-4L4 15Z M13 6l4 4',github:'M9 19c-5 2-5-2-7-2 M15 22v-4a4 4 0 0 0-1-3c4 0 7-2 7-6a5 5 0 0 0-1-3 5 5 0 0 0 0-4s-2 0-4 2a13 13 0 0 0-7 0C7 2 5 2 5 2a5 5 0 0 0 0 4 5 5 0 0 0-1 3c0 4 3 6 7 6a4 4 0 0 0-1 3v4',download:'M12 3v12 M7 10l5 5 5-5 M4 16v5h16v-5',copy:'M8 8h12v13H8z M4 16H2V2h13v2',calendar:'M4 5h16v16H4z M8 2v6 M16 2v6 M4 10h16'};
const icon=n=>`<svg aria-hidden="true" viewBox="0 0 24 24"><path d="${icons[n]||icons.dashboard}"/></svg>`;
const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const fmt=n=>n==null?'—':Number(n).toLocaleString('en-GB',{maximumFractionDigits:1});
const pct=(n,t)=>t?Math.min(100,Math.max(0,n/t*100)):0;
const requestedDate=new URLSearchParams(location.search).get('date');
const initialDate=requestedDate&&/^\d{4}-\d{2}-\d{2}$/.test(requestedDate)&&shiftDate(requestedDate,0)===requestedDate?requestedDate:today();
const state={readEpoch:0,data:null,date:initialDate,view:'dashboard',token:'',sha:null,sync:'Connecting to GitHub',error:'',loading:false,busy:false,loadedAt:null};
const root=document.querySelector('#app'),modal=document.querySelector('#modal');
const api=`https://api.github.com/repos/${REPO}/contents/${DATA_PATH}`;
function toast(msg){const el=document.querySelector('#toast');el.textContent=msg;el.style.display='block';clearTimeout(toast.timer);toast.timer=setTimeout(()=>el.style.display='none',5000);}
function jsonDecode(base64){return new TextDecoder().decode(Uint8Array.from(atob(base64.replace(/\s/g,'')),c=>c.charCodeAt(0)));}
function jsonEncode(text){const bytes=new TextEncoder().encode(text);let binary='';for(const byte of bytes)binary+=String.fromCharCode(byte);return btoa(binary);}
async function fetchRemote(){const headers={'Accept':'application/vnd.github+json','X-GitHub-Api-Version':'2022-11-28'};if(state.token)headers.Authorization=`Bearer ${state.token}`;const response=await fetch(api+'?ref=main&t='+Date.now(),{headers,cache:'no-store',signal:AbortSignal.timeout(15000)});if(!response.ok)throw Error(response.status===401?'GitHub did not accept the token.':response.status===403?'GitHub access was denied or its request limit was reached.':`GitHub returned ${response.status}.`);const file=await response.json();return {data:validate(JSON.parse(jsonDecode(file.content))),sha:file.sha};}
async function load({quiet=false}={}){if(state.loading||state.busy)return;state.loading=true;const epoch=++state.readEpoch;if(!quiet)state.sync='Refreshing…';if(state.data&&!quiet)render();try{const remote=await fetchRemote();if(epoch!==state.readEpoch)return;state.data=remote.data;state.sha=remote.sha;state.error='';state.sync='Live from GitHub';state.loadedAt=new Date();try{localStorage.setItem('cams-health-cache',JSON.stringify({data:state.data,at:state.loadedAt.toISOString()}));}catch{}}catch(error){if(epoch!==state.readEpoch)return;if(!state.data){try{const raw=await fetch(`https://raw.githubusercontent.com/${REPO}/main/${DATA_PATH}?t=${Date.now()}`,{cache:'no-store',signal:AbortSignal.timeout(10000)});if(!raw.ok)throw Error();state.data=validate(await raw.json());state.sync='Read from GitHub';state.loadedAt=new Date();}catch{try{const cached=JSON.parse(localStorage.getItem('cams-health-cache'));state.data=validate(cached.data);state.loadedAt=new Date(cached.at);state.sync='Saved browser copy';}catch{try{const response=await fetch('./data/health.json',{cache:'no-store'});state.data=validate(await response.json());state.sync='Published snapshot';}catch{root.innerHTML='<main class="main"><h1>Could not load your tracker</h1><p>Check your connection and reload this page.</p><button class="btn" onclick="location.reload()">Try again</button></main>';state.loading=false;return;}}}}else state.sync='Showing last loaded data';state.error=`${error.message} Refresh to check for newer records. This view may be out of date.`;}finally{state.loading=false;}render();}
function render(){if(!state.data)return;const data=state.data,p=data.profile,day=dayFor(data,state.date),t=totals(day);const title={dashboard:'Your daily dashboard',nutrition:'Food & nutrition',training:'Your training plan',history:'A little more every day',settings:'Make it yours'}[state.view];root.innerHTML=`<div class="shell"><aside class="sidebar"><div class="brand"><span class="brandmark">C</span><span class="brandtext">cam’s health<small>The daily work</small></span></div><div class="navcaption">Your workspace</div><nav class="nav" aria-label="Main navigation">${[['dashboard','Overview'],['nutrition','Nutrition'],['training','Training'],['history','History'],['settings','Settings']].map(([id,label])=>`<button data-view="${id}" class="${state.view===id?'active':''}" ${state.view===id?'aria-current="page"':''}>${icon(id)}<span>${label}</span></button>`).join('')}</nav><div class="sidebottom"><div class="syncside"><strong>${icon('github')} GitHub connected</strong>One place for every day.<br><a href="https://github.com/${REPO}" target="_blank" rel="noopener">View your records ↗</a></div><div class="person"><span class="avatar">CN</span><span>${esc(p.name)}<small>Building back stronger</small></span></div></div></aside><header class="topbar"><div class="breadcrumb">Your workspace <span>/</span> <strong>${{dashboard:'Overview',nutrition:'Nutrition',training:'Training',history:'History',settings:'Settings'}[state.view]}</strong></div><span class="mobilebrand">cam’s health</span><div class="topactions"><span class="syncbadge">${esc(state.sync)}</span><button class="iconbutton" data-action="refresh" aria-label="Refresh from GitHub" ${state.loading?'disabled':''}>${icon('refresh')}</button><button class="btn secondary" data-action="brief">${icon('download')} Daily brief</button></div></header><main class="main"><div class="heading"><div><p class="eyebrow">${state.view==='dashboard'?'One day at a time':'Cam’s health'}</p><h1>${title}</h1><p class="subtitle">${state.view==='dashboard'?'Your food, movement and training. All in one place.':state.view==='nutrition'?'See what’s logged and what’s left for today.':state.view==='training'?'Your existing program, ready when you are.':state.view==='history'?'Look back at the days you’ve recorded.':'Daily targets and your GitHub connection.'}</p></div><div class="headingactions">${!['settings','history'].includes(state.view)?`<div class="datecontrol"><button data-action="prev" aria-label="Previous day">${icon('left')}</button><input type="date" aria-label="Selected date" id="date" value="${state.date}"><button data-action="next" aria-label="Next day">${icon('right')}</button></div>`:''}<button class="btn" data-action="add">${icon('plus')}<span>Log something</span></button></div></div>${state.error?`<div class="errorbanner" role="status">${esc(state.error)}</div>`:''}${state.view==='dashboard'?dashboard(day,t):state.view==='nutrition'?nutrition(day,t):state.view==='training'?training():state.view==='history'?history():settings()}<footer class="pagefoot"><span>${state.loadedAt?'Last checked '+state.loadedAt.toLocaleTimeString('en-GB',{hour:'2-digit',minute:'2-digit'}):'Snapshot'} · ${esc(p.timezone)} · Estimates are marked</span><a href="https://github.com/${REPO}" target="_blank" rel="noopener">Saved in GitHub ↗</a></footer></main></div>`;bind();}
function metrics(day,t){const p=state.data.profile.targets,rem=p.kcal==null||t.missing.kcal?null:round(p.kcal-t.kcal);return `<section class="metrics" aria-label="Daily totals"><div class="card caloriecard"><div class="cardhead"><span class="cardlabel">${icon('flame')} Calories</span><span class="pill">${t.missing.kcal?'Known subtotal':t.estimated?'Estimated intake':'Logged intake'}</span></div><div><div class="calorietotal">${fmt(t.kcal)} <span>kcal</span></div><div class="muted">of ${fmt(p.kcal)} kcal daily target</div></div><div class="ring"><svg viewBox="0 0 128 128"><circle class="track" cx="64" cy="64" r="52"/><circle class="fill" cx="64" cy="64" r="52" stroke-dasharray="${pct(t.kcal,p.kcal)/100*326.73} 326.73"/></svg><div class="ringcenter">${p.kcal?Math.round(t.kcal/p.kcal*100)+'%':'—'}<small>of target</small></div></div><div class="caloriefoot"><span>${rem==null?(t.missing.kcal?'Some calories are unknown':'Set a calorie target'):rem>=0?fmt(rem)+' kcal remaining':fmt(-rem)+' kcal over target'}</span><span>${day.food.length} entries${t.pending?' · '+t.pending+' incomplete':''}</span></div></div><div class="card"><div class="cardhead"><span class="cardlabel">${icon('food')} Your macros</span></div>${[['protein','Protein'],['carbs','Carbs'],['fat','Fat']].map(([k,label])=>`<div class="macro"><strong>${label}</strong><span><b>${fmt(t[k])}g${t.missing[k]?' + ?':''}</b>${p[k]?' / '+fmt(p[k])+'g':''}</span><div class="bar"><i style="width:${p[k]?pct(t[k],p[k]):pct(t[k]*({protein:4,carbs:4,fat:9}[k]),t.protein*4+t.carbs*4+t.fat*9)}%"></i></div></div>`).join('')}<p class="macrofoot">${t.missing.protein?'Protein total is incomplete':p.protein?fmt(Math.max(0,round(p.protein-t.protein)))+'g protein to target':'Set your protein target'} · ${!p.carbs&&!p.fat?'Carbs & fat: share of macro energy':'Daily targets'}</p></div><div class="card stepscard"><div class="cardhead"><span class="cardlabel">${icon('steps')} Daily steps</span><button class="linkbutton" data-action="steps">${day.steps==null?'Log steps':'Update'} ${icon('plus')}</button></div><div class="stepvalue">${fmt(day.steps)} <small>/ ${fmt(p.steps)}</small></div><p class="steptext">${day.steps==null?'Your steps haven’t been logged yet.':!p.steps?'Set a daily step goal.':day.steps>=p.steps?'Daily step goal reached.':fmt(p.steps-day.steps)+' steps to your daily goal.'}</p><div class="bar"><i style="width:${pct(day.steps,p.steps)}%;background:#a9cd81"></i></div><div class="stepsfoot"><span>${day.steps==null?'Waiting for your update':p.steps?Math.round(day.steps/p.steps*100)+'% of daily goal':'No step goal set'}</span><span>${fmt(p.steps)} goal</span></div></div></section>`;}
function foodcard(day,t,full=false){return `<section class="card"><div class="cardhead"><h2>Food diary</h2><button class="linkbutton" data-action="food">Add food ${icon('plus')}</button></div><div class="foodlist">${day.food.length?day.food.map(f=>`<div class="foodrow"><div class="foodicon">${icon(/latte|coffee/i.test(f.name)?'coffee':'food')}</div><div><div class="foodname">${esc(f.name)}</div><div class="foodmeta">${esc(f.quantity)}${f.estimated?' · Estimated':''}<br>P ${fmt(f.protein)}g · C ${fmt(f.carbs)}g · F ${fmt(f.fat)}g</div>${full&&f.note?`<div class="entrynote">${esc(f.note)}</div>`:''}</div><div class="foodenergy">${fmt(f.kcal)}<small>kcal</small></div><button class="fooddelete" data-edit-food="${esc(f.id)}" aria-label="Edit ${esc(f.name)}">${icon('edit')}</button></div>`).join(''):'<div class="empty">No food logged for this day.<br>Add a meal, or tell me what you ate in chat.</div>'}</div><div class="foodfooter"><span>${day.food.length} entries${t.estimated?' · Nutrition estimated':''}</span><strong>${fmt(t.kcal)} kcal total</strong></div>${day.food.some(f=>f.reviewRequired)?'<div class="notice">One entry needs a nutrition check. Its recorded calories and macros don’t line up. Open Nutrition for the details.</div>':''}</section>`;}
function sessionItems(s,all=true){return `<ol class="exerciselist">${s.exercises.slice(0,all?99:4).map((e,i)=>`<li><span>${String(i+1).padStart(2,'0')}</span><strong>${esc(e.name)}</strong><small>${esc(e.sets)} × ${esc(e.reps)}</small></li>`).join('')}</ol>`;}
function workoutcard(day){const s=nextSession(state.data,state.date),done=day.workouts.filter(w=>w.status==='completed');return `<section class="card workoutcard"><div class="cardhead"><h2>${done.length?'Up next':'Next workout'}</h2><span class="pill">${s?.id==='rest'?'Recovery':'Your rotation'}</span></div><div class="workoutname"><span class="sessionbadge">${icon('training')}</span><h3>${esc(s?.name||'Choose a session')}</h3></div><p class="workoutsub">${esc(s?.focus||'Rest and recover.')} · ${s?.exercises.length||0} exercises</p>${s?sessionItems(s,false):''}${s?.exercises.length>4?`<button class="linkbutton" data-view="training" style="margin-top:10px">View all ${s.exercises.length} exercises ${icon('arrow')}</button>`:''}<button class="btn" data-action="workout">${icon('check')} Log completed session</button>${state.data.profile.trainingStatus==='awaiting clearance'?'<p class="workoutnote">Training is marked as awaiting clearance. This is your saved plan, not confirmation to resume hard training.</p>':''}${done.length?`<div class="statusbox">${done.map(w=>`${esc(w.name)} completed${w.durationMin!=null?' · '+fmt(w.durationMin)+' min':''}`).join('<br>')}</div>`:''}</section>`;}
function miniactivity(day){return `<div class="activityrow">${[['water','Water',day.waterMl==null?'—':fmt(day.waterMl/1000),'L','water'],['weight','Body weight',fmt(day.weightKg),'kg','weight']].map(([ic,label,value,unit,action])=>`<section class="card minicard"><div class="minihead">${label}${icon(ic)}</div><div class="minivalue">${value} <small>${unit}</small></div><div class="minifoot"><span>${value==='—'?'Not logged':'Recorded today'}</span><button class="linkbutton" data-action="${action}">Log ${icon('plus')}</button></div></section>`).join('')}</div>`;}
function weekchart(){const dates=Array.from({length:7},(_,i)=>shiftDate(state.date,i-6));const max=Math.max(state.data.profile.targets.kcal||1,...dates.map(d=>totals(dayFor(state.data,d)).kcal));return `<section class="card"><div class="cardhead"><h2>The last 7 days</h2><span class="pill">Calories</span></div><div class="chart" role="img" aria-label="Recorded daily calories for the last seven days">${dates.map(d=>{const value=totals(dayFor(state.data,d)).kcal,has=!!state.data.days[d]?.food.length;return `<div class="chartcol ${d===state.date?'selected':''}"><strong>${has?fmt(value):'—'}</strong><div class="column" style="height:${has?Math.max(3,value/max*80):2}px"></div><small>${new Date(d+'T12:00:00').toLocaleDateString('en-GB',{weekday:'short'})}</small></div>`;}).join('')}</div><div class="chartlegend">Unlogged days are blank, not zero intake.</div></section>`;}
function dashboard(day,t){return `${metrics(day,t)}<div class="gridmain"><div class="stack">${foodcard(day,t)}${miniactivity(day)}${day.notes?`<section class="card"><div class="cardhead"><h2>Day notes</h2><button class="linkbutton" data-action="notes">Edit</button></div><div class="notesbox">${esc(day.notes)}</div></section>`:''}</div><div class="stack rightstack">${workoutcard(day)}${weekchart()}</div></div><div class="brief"><div><strong>Just tell me how your day went.</strong><p>Send your food, steps or workout in chat. I’ll update your record and reply with your totals.</p></div><button class="btn secondary" data-action="chat">Copy chat prompt ${icon('copy')}</button></div>`;}
function nutrition(day,t){return `${metrics(day,t)}<div class="gridmain"><div class="stack">${foodcard(day,t,true)}</div><div class="stack"><section class="card"><div class="cardhead"><h2>Saved recipes</h2></div>${(state.data.recipes||[]).map(r=>`<div class="workoutlogged"><strong>${esc(r.name)}</strong><p class="help">${esc(r.note||r.notes||'Use a weighed portion of the cooked batch.')}<br>Batch yield: ${fmt(r.yieldGrams??r.yieldG)}g</p><button class="btn subtle" data-recipe="${esc(r.id)}">Log a portion</button></div>`).join('')||'<p class="help">Tell me your ingredients and cooked batch weight in chat to save a recipe.</p>'}</section>${weekchart()}</div></div>`;}
function training(){const next=nextSession(state.data,state.date);return `${state.data.profile.trainingStatus==='awaiting clearance'?'<div class="notice" style="margin:0 0 20px">Your saved context says training is awaiting clearance. Keep this plan on hold until you are cleared; update that status in Settings when appropriate.</div>':''}<div class="card" style="margin-bottom:20px"><div class="cardhead"><h2>Next in your rotation: ${esc(next?.name)}</h2><button class="btn" data-action="workout">Log a session</button></div><p class="help">${state.data.training.rotation.map(id=>esc(state.data.training.sessions.find(s=>s.id===id)?.name)).join(' → ')}<br>The rotation advances only when a session is logged as completed. Missing a day does not skip a workout.</p><p class="help">${esc(Array.isArray(state.data.training.notes)?state.data.training.notes.join(' '):state.data.training.notes||'')}</p></div><div class="traininggrid">${state.data.training.sessions.map(s=>`<section class="card"><div class="cardhead"><h2>${esc(s.name)}</h2>${s.id===next?.id?'<span class="pill">Up next</span>':''}</div><p class="help">${esc(s.focus)}</p>${sessionItems(s)}${s.exercises.some(e=>e.note)?`<details class="help" style="margin-top:16px"><summary>Exercise notes & rest</summary>${s.exercises.map(e=>`<p><b>${esc(e.name)}:</b> ${esc(e.note||'')}${e.rest?' Rest '+esc(e.rest)+' seconds.':''}</p>`).join('')}</details>`:''}<button class="btn subtle" style="margin-top:15px" data-session="${esc(s.id)}">Log ${esc(s.name)}</button></section>`).join('')}</div>${workoutHistory()}`;}
function workoutHistory(){const days=Object.entries(state.data.days).filter(([,d])=>d.workouts.length).sort(([a],[b])=>b.localeCompare(a));return `<section class="card" style="margin-top:22px"><h2>Recorded sessions</h2>${days.length?days.map(([date,day])=>day.workouts.map(w=>`<div class="workoutlogged"><strong>${esc(w.name)}</strong> · ${date} · ${esc(w.status)} · ${w.durationMin==null?'Duration not logged':fmt(w.durationMin)+' min'}<br>${esc(w.notes||'')}<button class="linkbutton" data-edit-workout="${esc(w.id)}" data-workout-date="${date}">Edit session</button></div>`).join('')).join(''):'<p class="empty">No completed sessions recorded yet.</p>'}</section>`;}
function history(){const dates=Object.keys(state.data.days).sort().reverse(),foodDays=dates.filter(d=>state.data.days[d].food.length),sum=foodDays.reduce((s,d)=>s+totals(state.data.days[d]).kcal,0),sessions=dates.reduce((s,d)=>s+state.data.days[d].workouts.filter(w=>w.status==='completed'&&w.sessionId!=='rest').length,0);return `<section class="card"><div class="cardhead"><h2>Your record</h2><button class="btn secondary" data-action="export">${icon('download')} Export JSON</button></div><div class="historysummary"><div><strong>${dates.length}</strong>days with records</div><div><strong>${foodDays.length?fmt(Math.round(sum/foodDays.length)):'—'}</strong>average logged kcal*</div><div><strong>${sessions}</strong>completed workouts</div></div><p class="help">*Includes partial food logs. This is not an estimate of your true average intake.</p><div class="tablewrap"><table><thead><tr><th>Date</th><th>Calories</th><th>Protein</th><th>Carbs</th><th>Fat</th><th>Steps</th><th>Training</th><th>Weight</th></tr></thead><tbody>${dates.map(date=>{const d=state.data.days[date],t=totals(d);return `<tr><td><button data-date="${date}">${date}</button></td><td>${d.food.length?fmt(t.kcal):'—'}${t.estimated?' ≈':''}${t.pending?' · incomplete':''}</td><td>${d.food.length?fmt(t.protein)+'g':'—'}</td><td>${d.food.length?fmt(t.carbs)+'g':'—'}</td><td>${d.food.length?fmt(t.fat)+'g':'—'}</td><td>${fmt(d.steps)}</td><td>${d.workouts.map(w=>esc(w.name)).join(', ')||'—'}</td><td>${fmt(d.weightKg)}${d.weightKg?' kg':''}</td></tr>`;}).join('')}</tbody></table></div></section>`;}
function settings(){const p=state.data.profile;return `<div class="settinggrid"><section class="card"><div class="cardhead"><h2>Your daily targets</h2></div><form id="targets" class="settingsform">${[['kcal','Calories','kcal'],['protein','Protein','g'],['carbs','Carbs (optional)','g'],['fat','Fat (optional)','g'],['steps','Steps','steps']].map(([key,label,unit])=>`<label class="field">${label} · ${unit}<input type="number" name="${key}" min="0" max="100000" step="${key==='steps'?'1':'0.1'}" value="${p.targets[key]??''}" ${['kcal','protein','steps'].includes(key)?'required':''}></label>`).join('')}<label class="field">Training status<select name="trainingStatus"><option value="awaiting clearance" ${p.trainingStatus==='awaiting clearance'?'selected':''}>Awaiting clearance</option><option value="ready" ${p.trainingStatus==='ready'?'selected':''}>Ready to train</option><option value="paused" ${p.trainingStatus==='paused'?'selected':''}>Paused</option></select></label><p class="help full">Targets are your saved preferences. Exercise calories are not automatically added to your food allowance.</p><button class="btn full" type="submit">Save targets to GitHub</button></form></section><section class="card"><h2>GitHub connection</h2><p class="help">Your data lives in <a href="https://github.com/${REPO}/blob/main/${DATA_PATH}" target="_blank" rel="noopener">${REPO}</a>. This repository is public, so committed records are public.</p><div class="statusbox">${state.token?'Browser editing is connected for this tab.':'Chat logging is ready. Browser editing is optional.'}</div><p class="help">To log in this app, use a fine-grained GitHub token scoped to this repository with Contents: Read and write. The token is held only in this tab’s memory, sent only to GitHub, and cleared when you reload or disconnect.</p><form id="connect"><label class="field">GitHub token<input type="password" name="token" autocomplete="off" placeholder="github_pat_…" required></label><div class="modalactions"><button class="btn" type="submit">Connect for this tab</button>${state.token?'<button class="btn secondary" type="button" data-action="disconnect">Disconnect</button>':''}</div></form><p class="help">No token is needed to view the dashboard or to ask me to update it through the connected GitHub plugin.</p></section><section class="card"><h2>Your data</h2><p class="help">The app refreshes from GitHub when opened, when you return to the tab, and every five minutes. A browser cache is only a fallback; it is never treated as a new save.</p><button class="btn secondary" data-action="export">${icon('download')} Download all records</button></section><section class="card"><h2>Logging through chat</h2><p class="help">Tell me what you ate, how much you walked or what you trained. I’ll update the GitHub record and reply with your day’s totals. Include quantities for a useful food estimate.</p><button class="btn subtle" data-action="chat">Copy a starter prompt</button></section></div>`;}
function bind(){const displayedProfile=structuredClone(state.data.profile);document.querySelectorAll('[data-view]').forEach(b=>b.onclick=()=>{state.view=b.dataset.view;render();window.scrollTo(0,0);});document.querySelector('#date')?.addEventListener('change',e=>{if(/^\d{4}-\d{2}-\d{2}$/.test(e.target.value)){state.date=e.target.value;render();}});document.querySelectorAll('[data-action]').forEach(b=>b.onclick=()=>action(b.dataset.action));document.querySelectorAll('[data-edit-food]').forEach(b=>b.onclick=()=>foodForm(b.dataset.editFood));document.querySelectorAll('[data-session]').forEach(b=>b.onclick=()=>workoutForm(null,b.dataset.session));document.querySelectorAll('[data-edit-workout]').forEach(b=>b.onclick=()=>{state.date=b.dataset.workoutDate;workoutForm(b.dataset.editWorkout);});document.querySelectorAll('[data-date]').forEach(b=>b.onclick=()=>{state.date=b.dataset.date;state.view='dashboard';render();});document.querySelectorAll('[data-recipe]').forEach(b=>b.onclick=()=>recipeForm(b.dataset.recipe));document.querySelector('#connect')?.addEventListener('submit',async e=>{e.preventDefault();const token=new FormData(e.target).get('token').trim();state.token=token;try{await fetchRemote();toast('Connected for this tab.');await load();}catch(error){state.token='';toast(error.message);}});document.querySelector('#targets')?.addEventListener('submit',async e=>{e.preventDefault();const baselineTargets=displayedProfile.targets,baselineStatus=displayedProfile.trainingStatus;const form=new FormData(e.target),targets={};for(const k of ['kcal','protein','carbs','fat','steps'])targets[k]=form.get(k)===''?null:Number(form.get(k));try{await save(d=>{assertUnchanged(d.profile.targets,baselineTargets);assertUnchanged(d.profile.trainingStatus,baselineStatus);d.profile.targets=targets;d.profile.trainingStatus=form.get('trainingStatus');},'Update daily fitness targets');}catch(error){toast(error.message);}});}
async function action(id){if(id==='refresh')return load();if(id==='prev'||id==='next'){state.date=shiftDate(state.date,id==='prev'?-1:1);return render();}if(id==='food')return foodForm();if(id==='workout')return workoutForm();if(['steps','water','weight','notes'].includes(id))return metricForm(id);if(id==='add')return showModal('What would you like to log?',`<div class="choices">${[['food','Food or drink'],['workout','Workout'],['steps','Steps'],['water','Water'],['weight','Body weight'],['notes','Day notes']].map(([key,label])=>`<button class="choice" data-log="${key}">${icon(key==='workout'?'training':key)}${label}</button>`).join('')}</div>`,()=>modal.querySelectorAll('[data-log]').forEach(b=>b.onclick=()=>action(b.dataset.log)));if(id==='brief')return showModal('Your daily brief',`<p class="help">${esc(state.date)} · Totals from your saved record</p><pre class="notesbox">${esc(brief(state.data,state.date))}</pre><div class="modalactions"><button class="btn secondary" id="copybrief">Copy totals</button><button class="btn" id="printbrief">Print / save PDF</button></div>`,()=>{modal.querySelector('#copybrief').onclick=()=>copy(brief(state.data,state.date));modal.querySelector('#printbrief').onclick=()=>{modal.close();state.view='dashboard';render();window.print();};});if(id==='chat')return copy(`Use my fitness tracker in https://github.com/${REPO}. Read AGENTS.md and ${DATA_PATH} first. Log the following for ${state.date}, commit it, and send my updated daily totals and next workout: [tell you what I ate or did here]`);if(id==='export'){const a=document.createElement('a');a.href=URL.createObjectURL(new Blob([JSON.stringify(state.data,null,2)],{type:'application/json'}));a.download=`cams-health-${today()}.json`;a.click();URL.revokeObjectURL(a.href);}if(id==='disconnect'){state.token='';render();toast('Browser editing disconnected.');}}
async function copy(text){try{await navigator.clipboard.writeText(text);toast('Copied to clipboard.');}catch{showModal('Copy this text',`<textarea class="full" style="width:100%;height:190px">${esc(text)}</textarea>`);}}
function showModal(title,body,setup){modal.innerHTML=`<div class="modalhead"><h2>${title}</h2><button class="iconbutton" id="closemodal" aria-label="Close dialog">${icon('close')}</button></div>${body}`;modal.querySelector('#closemodal').onclick=()=>modal.close();if(!modal.open)modal.showModal();setup?.();}
function authHelp(){return '<p class="help full">Saves directly to GitHub. To enable browser editing, connect your token in Settings. You can also send this update in chat.</p>';}
function foodForm(id){const date=state.date,existing=dayFor(state.data,date).food.find(f=>f.id===id),f=existing||{},entryId=f.id||crypto.randomUUID();showModal(existing?'Edit food':'Log food or drink',`<form id="logform"><div class="formgrid"><label class="field full">Food or drink<input name="name" value="${esc(f.name)}" required maxlength="160" placeholder="e.g. Beef mince and rice"></label><label class="field full">Portion<input name="quantity" value="${esc(f.quantity)}" required maxlength="160" placeholder="e.g. 200g cooked mince + 150g cooked rice"></label>${[['kcal','Calories · kcal'],['protein','Protein · g'],['carbs','Carbs · g'],['fat','Fat · g']].map(([k,l])=>`<label class="field">${l}<input type="number" name="${k}" min="0" max="100000" step="0.1" value="${f[k]??''}" placeholder="Unknown"></label>`).join('')}<label class="checkfield full"><input type="checkbox" name="estimated" ${f.estimated!==false?'checked':''}> Nutrition is an estimate</label><label class="field full">Notes / nutrition source<textarea name="note">${esc(f.note)}</textarea></label>${authHelp()}</div><p class="formerror" id="formerror"></p><div class="modalactions">${existing?'<button class="btn secondary" type="button" id="deleteentry">Delete entry</button>':''}<button class="btn" type="submit">Save food</button></div></form>`,()=>{modal.querySelector('#logform').onsubmit=async e=>{e.preventDefault();const fd=new FormData(e.target),food={...f,id:entryId,name:fd.get('name').trim(),quantity:fd.get('quantity').trim(),estimated:fd.has('estimated'),note:fd.get('note').trim(),source:f.source||'Manually entered',loggedAt:f.loggedAt||new Date().toISOString()};for(const k of ['kcal','protein','carbs','fat'])food[k]=fd.get(k)===''?null:Number(fd.get(k));food.reviewRequired=food.kcal!=null&&[food.protein,food.carbs,food.fat].every(v=>v!=null)&&Math.abs(food.kcal-(food.protein*4+food.carbs*4+food.fat*9))>Math.max(25,food.kcal*.1);await submit(async()=>save(d=>{const day=ensureDay(d,date);if(existing){const i=day.food.findIndex(x=>x.id===id);if(i<0)throw Error('This entry changed elsewhere. Refresh and try again.');assertUnchanged(day.food[i],f);day.food[i]=food;}else if(!day.food.some(x=>x.id===entryId))day.food.push(food);},`${existing?'Correct':'Log'} food for ${date}`));};if(existing)modal.querySelector('#deleteentry').onclick=()=>confirmDelete('Delete this food entry?',()=>save(d=>{const day=ensureDay(d,date);const current=day.food.find(x=>x.id===id);if(current)assertUnchanged(current,f);day.food=day.food.filter(x=>x.id!==id);},`Delete food entry for ${date}`));});}
function workoutForm(id,sessionId){const date=state.date,existing=dayFor(state.data,date).workouts.find(w=>w.id===id),next=nextSession(state.data,date),w=existing||{},entryId=w.id||crypto.randomUUID(),selected=sessionId||w.sessionId||next?.id;showModal(existing?'Edit session':'Log a completed session',`<form id="logform"><div class="formgrid"><label class="field full">Session<select name="sessionId">${state.data.training.sessions.map(s=>`<option value="${esc(s.id)}" ${s.id===selected?'selected':''}>${esc(s.name)}</option>`).join('')}<option value="custom" ${w.sessionId===null?'selected':''}>Other activity</option></select></label><label class="field full">Activity name (for other activity)<input name="name" value="${esc(w.sessionId===null?w.name:'')}" maxlength="160" placeholder="e.g. Easy cycling"></label><label class="field">Duration · minutes<input type="number" name="durationMin" min="1" max="1440" step="1" value="${w.durationMin??''}" placeholder="e.g. 90"></label><label class="field">Status<select name="status"><option value="completed" ${w.status!=='partial'?'selected':''}>Completed</option><option value="partial" ${w.status==='partial'?'selected':''}>Partial / stopped early</option></select></label><label class="field full">Actual exercises, weights, reps or notes<textarea name="notes" placeholder="Only record what you actually did.">${esc(w.notes)}</textarea></label>${authHelp()}</div><p class="formerror" id="formerror"></p><div class="modalactions">${existing?'<button class="btn secondary" type="button" id="deleteentry">Delete session</button>':''}<button class="btn" type="submit">Save session</button></div></form>`,()=>{modal.querySelector('#logform').onsubmit=async e=>{e.preventDefault();const fd=new FormData(e.target),sid=fd.get('sessionId'),s=state.data.training.sessions.find(x=>x.id===sid),entry={...w,id:entryId,sessionId:sid==='custom'?null:sid,name:s?.name||fd.get('name').trim(),status:fd.get('status'),durationMin:fd.get('durationMin')===''?null:Number(fd.get('durationMin')),notes:fd.get('notes').trim(),loggedAt:w.loggedAt||new Date().toISOString()};if(!entry.name){modal.querySelector('#formerror').textContent='Enter an activity name.';return;}await submit(()=>save(d=>{const day=ensureDay(d,date);if(existing){const i=day.workouts.findIndex(x=>x.id===id);if(i<0)throw Error('Session no longer exists. Refresh and try again.');assertUnchanged(day.workouts[i],w);day.workouts[i]=entry;}else if(!day.workouts.some(x=>x.id===entryId))day.workouts.push(entry);},`Log training for ${date}`));};if(existing)modal.querySelector('#deleteentry').onclick=()=>confirmDelete('Delete this session?',()=>save(d=>{const day=ensureDay(d,date),current=day.workouts.find(x=>x.id===id);if(current)assertUnchanged(current,w);day.workouts=day.workouts.filter(x=>x.id!==id);},`Delete session for ${date}`));});}
function metricForm(type){const config={steps:['Daily steps','steps','Total steps for the day',200000,1],water:['Water intake','waterMl','Total water today · ml',20000,1],weight:['Body weight','weightKg','Weight · kg',500,.1],notes:['Day notes','notes','Notes',0,0]}[type],date=state.date,[title,key,label,max,step]=config,value=dayFor(state.data,date)[key],baseline=value;showModal(title,`<form id="logform"><label class="field">${label}${type==='notes'?`<textarea name="value" maxlength="5000">${esc(value)}</textarea>`:`<input type="number" name="value" value="${value??''}" min="0" max="${max}" step="${step}" placeholder="Not logged">`}</label><p class="help">${type==='steps'||type==='water'?'Enter your total for the day. This replaces the existing total; it does not add to it.':type==='weight'?'Use a consistent measurement time. Blank removes the measurement.':'Saved with this date.'}</p>${authHelp()}<p class="formerror" id="formerror"></p><div class="modalactions"><button class="btn" type="submit">Save ${type}</button></div></form>`,()=>modal.querySelector('#logform').onsubmit=async e=>{e.preventDefault();const value=new FormData(e.target).get('value');await submit(()=>save(d=>{assertUnchanged(ensureDay(d,date)[key],baseline);ensureDay(d,date)[key]=type==='notes'?value:value===''?null:Number(value);},`Update ${type} for ${date}`));});}
function recipeForm(id){const r=state.data.recipes.find(x=>x.id===id),entryId=crypto.randomUUID();showModal('Log a recipe portion',`<form id="logform"><h3>${esc(r.name)}</h3><label class="field">Cooked portion · grams<input name="grams" type="number" min="1" max="10000" required step="1"></label><p class="help">Nutrition is scaled from the saved recipe. Ingredient assumptions remain estimates.</p>${authHelp()}<p class="formerror" id="formerror"></p><div class="modalactions"><button class="btn" type="submit">Save portion</button></div></form>`,()=>{const date=state.date;modal.querySelector('#logform').onsubmit=async e=>{e.preventDefault();const grams=Number(new FormData(e.target).get('grams')),per=r.per100g||r.per100Grams;if(!per){modal.querySelector('#formerror').textContent='Recipe nutrition needs updating in GitHub first.';return;}const entry={id:entryId,recipeId:r.id,portionGrams:grams,name:r.name,quantity:grams+'g cooked portion',estimated:true,source:'Saved recipe '+r.id,note:r.note||r.notes||'',loggedAt:new Date().toISOString()};for(const k of ['kcal','protein','carbs','fat'])entry[k]=per[k]==null?null:round(per[k]*grams/100);await submit(()=>save(d=>{const day=ensureDay(d,date);if(!day.food.some(x=>x.id===entryId))day.food.push(entry);},`Log recipe portion for ${date}`));};});}
function assertUnchanged(current,baseline){if(JSON.stringify(current)!==JSON.stringify(baseline))throw Error('This record changed on GitHub while you were editing. Close this form, refresh, and retry. Nothing was overwritten.');}
function ensureDay(data,date){if(!data.days[date])data.days[date]={food:[],workouts:[],steps:null,waterMl:null,weightKg:null,notes:''};return data.days[date];}
async function submit(fn){const form=modal.querySelector('form'),btn=form?.querySelector('[type=submit]');if(btn)btn.disabled=true;try{await fn();modal.close();}catch(error){const target=modal.querySelector('#formerror');if(target)target.textContent=error.message;else toast(error.message);}finally{if(btn)btn.disabled=false;}}
function confirmDelete(title,fn){showModal(title,'<p class="help">The current record will be removed. Previous versions remain in GitHub’s commit history.</p><p class="formerror" id="formerror"></p><div class="modalactions"><button class="btn secondary" id="canceldelete">Cancel</button><button class="btn danger" id="confirmdelete">Delete</button></div>',()=>{modal.querySelector('#canceldelete').onclick=()=>modal.close();modal.querySelector('#confirmdelete').onclick=async e=>{e.target.disabled=true;try{await fn();modal.close();}catch(error){modal.querySelector('#formerror').textContent=error.message;e.target.disabled=false;}};});}
async function save(mutate,message){if(!state.token)throw Error('Connect a GitHub token in Settings to save here, or send this update to me in chat. Nothing has been saved.');if(state.busy)throw Error('A save is already in progress.');state.busy=true;state.readEpoch++;try{const fresh=await fetchRemote();const data=structuredClone(fresh.data);mutate(data);data.updatedAt=new Date().toISOString();validate(data);const response=await fetch(api,{method:'PUT',headers:{'Authorization':`Bearer ${state.token}`,'Accept':'application/vnd.github+json','Content-Type':'application/json','X-GitHub-Api-Version':'2022-11-28'},body:JSON.stringify({message,content:jsonEncode(JSON.stringify(data,null,2)+'\n'),sha:fresh.sha,branch:'main'}),signal:AbortSignal.timeout(20000)});if(!response.ok)throw Error(response.status===409||response.status===422?'The record changed during your save. Refresh and retry; nothing was overwritten.':`GitHub save failed (${response.status}). Check repository write access.`);const result=await response.json();state.data=data;state.sha=result.content.sha;state.sync='Saved to GitHub';state.error='';state.loadedAt=new Date();try{localStorage.setItem('cams-health-cache',JSON.stringify({data,at:state.loadedAt.toISOString()}));}catch{}render();toast('Saved to GitHub. Your totals are updated.');}catch(error){if(error.name==='TimeoutError'||error.name==='TypeError')throw Error('The save could not be confirmed. Refresh before retrying to avoid logging twice.');throw error;}finally{state.busy=false;}}
document.addEventListener('visibilitychange',()=>{if(document.visibilityState==='visible'&&!modal.open)load({quiet:true});});setInterval(()=>{if(document.visibilityState==='visible'&&!modal.open)load({quiet:true});},300000);load();
